begin;
create table bpv.products (id uuid primary key,revision bigint not null default 0 check(revision>=0),code text not null unique check(length(trim(code)) between 1 and 60),snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),updated_at timestamptz not null default now(),updated_by uuid not null references auth.users(id));
create table bpv.product_revisions (product_id uuid not null references bpv.products(id),revision bigint not null,snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),actor uuid not null references auth.users(id),created_at timestamptz not null default now(),primary key(product_id,revision));
alter table bpv.products enable row level security; alter table bpv.product_revisions enable row level security;
revoke all on bpv.products,bpv.product_revisions from public,anon,authenticated;
grant select,insert,update on bpv.products to service_role; grant select,insert on bpv.product_revisions to service_role;
create function public.bpv_list_products(p_actor uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,bpv as $$ begin if not public.bpv_has_permission(p_actor,'promotions.manage') then raise exception 'FORBIDDEN'; end if; return coalesce((select jsonb_agg(snapshot||jsonb_build_object('remoteRevision',revision) order by lower(snapshot->>'name'),id) from bpv.products),'[]'); end $$;
create function public.bpv_write_product(p_actor uuid,p_id uuid,p_expected_revision bigint,p_product jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,bpv as $$ declare current bpv.products;saved bpv.products;normalized_code text; begin if not public.bpv_has_permission(p_actor,'promotions.manage') then raise exception 'FORBIDDEN'; end if; perform pg_advisory_xact_lock(hashtextextended('bpv.product:'||p_id::text,0)); select * into current from bpv.products where id=p_id for update; if p_expected_revision is null or p_expected_revision<>coalesce(current.revision,0) then raise exception 'REVISION_CONFLICT'; end if; if p_product is null or p_product->>'id'<>p_id::text then raise exception 'INVALID_PRODUCT'; end if; normalized_code=trim(p_product->>'code'); if coalesce(length(normalized_code),0)=0 then raise exception 'INVALID_PRODUCT'; end if; insert into bpv.products(id,revision,code,snapshot,updated_by) values(p_id,1,normalized_code,p_product,p_actor) on conflict(id) do update set revision=bpv.products.revision+1,code=excluded.code,snapshot=excluded.snapshot,updated_at=now(),updated_by=p_actor returning * into saved; insert into bpv.product_revisions(product_id,revision,snapshot,actor) values(saved.id,saved.revision,saved.snapshot,p_actor); return saved.snapshot||jsonb_build_object('remoteRevision',saved.revision); end $$;
revoke all on function public.bpv_list_products(uuid),public.bpv_write_product(uuid,uuid,bigint,jsonb) from public,anon,authenticated;
grant execute on function public.bpv_list_products(uuid),public.bpv_write_product(uuid,uuid,bigint,jsonb) to service_role;
commit;
